import itertools
def can_pair(a,b):
    pairs={('A','U'),('U','A'),('G','C'),('C','G'),('G','U'),('U','G')}
    return (a,b) in pairs
def revcomp(s):
    m={'A':'U','U':'A','G':'C','C':'G'}; return ''.join(m[c] for c in s[::-1])
def crosspair_tt(a,b):
    n=len(a)
    return all(can_pair(a[k],b[n-1-k]) for k in range(n))
def crosspair_tb(a,b):
    bot=revcomp(b); n=len(a)
    return all(can_pair(a[k],bot[n-1-k]) for k in range(n))
def self_comp(s):
    # self-complementary (hairpin) 
    return crosspair_tt(s,s)

# Generate all 3-mers
bases='ACGU'
all3=[''.join(p) for p in itertools.product(bases,repeat=4)]  # typo
all3=[''.join(p) for p in itertools.product(bases,repeat=3)]
# filter out self-complementary (would form own hairpin)
all3=[s for s in all3 if not self_comp(s)]
print('non-self-comp 3mers',len(all3))

# Find a set of 12 stems with no cross-pairing (tt or tb) among any pair.
# This is a graph independent-set problem. Build conflict graph.
def conflicts(a,b):
    if a==b: return False  # same stem is fine (we won't reuse)
    return crosspair_tt(a,b) or crosspair_tb(a,b) or crosspair_tb(b,a)
# Note tt is symmetric. tb not necessarily.
# Greedy: prefer GC-rich for junctions.
# First sort by GC content desc
all3.sort(key=lambda s:-(sum(1 for c in s if c in 'GC')))
# Find max independent set via greedy
picked=[]
for s in all3:
    if any(conflicts(s,p) for p in picked): continue
    picked.append(s)
    if len(picked)>=14: break
print('picked',len(picked),picked)
# Verify
for a,b in itertools.combinations(picked,2):
    if conflicts(a,b): print('CONFLICT',a,b)
print('gc counts',[(s,sum(1 for c in s if c in 'GC')) for s in picked])
